+static int serial_ambarella_verify_port(struct uart_port *port,
+                                       struct serial_struct *ser)
+{
+       int rval = 0;
+
+       if (ser->type != PORT_UNKNOWN && ser->type != PORT_UART00)
+               rval = -EINVAL;
+       if (port->irq != ser->irq)
+               rval = -EINVAL;
+       if (ser->io_type != SERIAL_IO_MEM)
+               rval = -EINVAL;
+
+       return rval;
+}
